def preserve_profile(apps, schema_editor):
    Workspace = apps.get_model("workspaces", "Workspace")
    Index = apps.get_model("documents", "IndexVersion")
    for workspace in Workspace.objects.using(schema_editor.connection.alias).iterator():
        profiles = list(
            Index.objects.using(schema_editor.connection.alias)
            .filter(active=True, extraction__source__document__collection__workspace=workspace)
            .values_list("profile", flat=True)
        )
        if profiles and all(profile == profiles[0] for profile in profiles):
            workspace.index_profile = profiles[0]
            workspace.save(update_fields=["index_profile"], using=schema_editor.connection.alias)


